// Cloudflare entry point: the OpenNext handler plus the realtime Durable Object.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import { default as handler } from "./.open-next/worker.js";
import { HUB_NAME } from "./src/server/realtime/hub-name";

export { RealtimeHub } from "./src/server/realtime/hub";

type Next = {
  fetch: (request: Request, env: CloudflareEnv, ctx: ExecutionContext) => Promise<Response>;
};
const next = handler as Next;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === "/api/realtime" && request.headers.get("Upgrade") === "websocket") {
      // Same-origin only: the session cookie must not be usable from another site.
      const origin = request.headers.get("Origin");
      if (origin && origin !== url.origin)
        return new Response("Origem não autorizada.", { status: 403 });
      // Ask the app (same isolate, no network hop) which channels this session may join.
      const lookup = await next.fetch(
        new Request(url, { headers: { cookie: request.headers.get("cookie") || "" } }),
        env,
        ctx,
      );
      if (!lookup.ok) return new Response("Faça login para continuar.", { status: 401 });
      const { channels } = (await lookup.json()) as { channels: string[] };
      const hub = env.REALTIME.get(env.REALTIME.idFromName(HUB_NAME));
      const headers = new Headers(request.headers);
      headers.set("X-Realtime-Channels", JSON.stringify(channels));
      return hub.fetch(new Request(request.url, { headers }));
    }
    return next.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
